const $ = (id) => document.getElementById(id);

function buildScript({ user, pass, grade, solutions, headless }) {
  const gradeLabel = grade === "1" ? "أولى ثانوي" : "تانية ثانوي";
  const solLine = solutions
    ? `await try_solutions(context, SOLUTIONS_URL)`
    : `print("[i] تم تخطي جلب الحلول")`;
  const headlessVal = headless ? "True" : "False";

  return `#!/usr/bin/env python3
# qureo_solver.py — generated by SOLEVER
# $$[MADE BY NullRoutee]$$
import asyncio
from playwright.async_api import async_playwright

QUREO_USER = "${user.replace(/"/g, '\\"')}"
QUREO_PASS = "${pass.replace(/"/g, '\\"')}"
GRADE_LABEL = "${gradeLabel}"
SOLUTIONS_URL = "https://qureoeg.com/qureo-solutions"
HEADLESS = ${headlessVal}

def print(msg):
    print(msg, flush=True)

async def try_solutions(context, url):
    print(f"[sol] محاولة فتح {url}")
    try:
        page = await context.new_page()
        resp = await page.goto(url, wait_until="domcontentloaded", timeout=15000)
        if resp and resp.status >= 400:
            print(f"[sol] الرد {resp.status} — الرابط غير متاح")
            return
        await page.wait_for_timeout(2500)
        title = await page.title()
        print(f"[sol] عنوان الصفحة: {title}")
        await page.screenshot(path="solutions_page.png", full_page=True)
        print("[sol] تم حفظ solutions_page.png")
    except Exception as e:
        print(f"[sol] فشل: {e}")

async def main():
    async with async_playwright() as p:
        browser = await p.chromium.launch(headless=HEADLESS)
        context = await browser.new_context()
        page = await context.new_page()

        print("[1] فتح صفحة تسجيل الدخول...")
        await page.goto("https://me-portal.qureo.education/login", wait_until="networkidle")
        await page.wait_for_timeout(2000)

        # حقول الدخول
        user_input = page.locator('input[type="text"], input[name*="user"], input[id*="user"]').first
        pass_input = page.locator('input[type="password"]').first

        if await user_input.count() > 0 and await pass_input.count() > 0:
            await user_input.fill(QUREO_USER)
            await pass_input.fill(QUREO_PASS)
            print("[2] تم إدخال البيانات")
        else:
            print("[!] لم يتم العثور على حقول الإدخال — تحقق يدوياً")
            await page.screenshot(path="debug_login.png", full_page=True)

        btn = page.locator('button[type="submit"], button:has-text("ログイン"), button:has-text("Login")').first
        if await btn.count() > 0:
            await btn.click()
            print("[3] تم النقر على تسجيل الدخول")
        else:
            print("[!] لم يتم العثور على زر الدخول — تحقق يدوياً")

        await page.wait_for_timeout(5000)
        await page.screenshot(path="after_login.png", full_page=True)
        print("[4] حفظ after_login.png")

        # اختيار الصف
        print(f"[5] البحث عن خيار: {GRADE_LABEL}")
        candidates = [
            page.locator(f'text={GRADE_LABEL}').first,
            page.locator('text=اولی ثانوی').first,
            page.locator('text=1年生').first,
            page.locator('text=First Year').first,
        ]
        picked = False
        for loc in candidates:
            try:
                if await loc.count() > 0:
                    await loc.click()
                    print(f"[6] تم اختيار {GRADE_LABEL}")
                    picked = True
                    await page.wait_for_timeout(3000)
                    break
            except Exception:
                continue
        if not picked:
            print("[i] لم يتم العثور على خيار الصف — قد يكون الحساب محدداً مسبقاً")

        await page.screenshot(path="grade_selected.png", full_page=True)
        print("[7] حفظ grade_selected.png")

        # محتوى JavaScript
        print("[8] البحث عن محتوى JavaScript...")
        js_items = await page.locator('text=JavaScript, text=javascript, text=JS').all()
        if js_items:
            for i, item in enumerate(js_items[:8]):
                try:
                    txt = (await item.text_content() or "").strip()
                    if txt:
                        print(f"  [js{i}] {txt[:120]}")
                except Exception:
                    pass
        else:
            print("  [!] لا يوجد محتوى JavaScript ظاهر")

        # رابط الحلول
        ${solLine}

        print("\\n=== اكتمل التشغيل — راجع لقطات الشاشة ===")
        if not HEADLESS:
            input("اضغط Enter للإغلاق...")
        await browser.close()

if __name__ == "__main__":
    asyncio.run(main())
`;
}

function generate() {
  const user = $("user").value.trim();
  const pass = $("pass").value;
  const grade = document.querySelector('input[name="grade"]:checked').value;
  const solutions = $("solutions").checked;
  const headless = $("headless").checked;

  if (!user || !pass) {
    alert("املأ اسم المستخدم وكلمة المرور الأول");
    return;
  }

  const code = buildScript({ user, pass, grade, solutions, headless });
  $("output").textContent = code;
  $("output-block").hidden = false;
  $("copy").disabled = false;
  $("output-block").scrollIntoView({ behavior: "smooth", block: "start" });
}

async function copyCode() {
  const code = $("output").textContent;
  try {
    await navigator.clipboard.writeText(code);
    const btn = $("copy");
    const old = btn.textContent;
    btn.textContent = "تم النسخ ✓";
    setTimeout(() => (btn.textContent = old), 1500);
  } catch {
    alert("النسخ فشل — حدد النص يدوياً");
  }
}

$("generate").addEventListener("click", generate);
$("copy").addEventListener("click", copyCode);
